INSERT INTO `frequently_asked_questions` (`id`, `question`, `answer`, `created_at`, `updated_at`) VALUES
(1, 'ما هي سياسة الإرجاع للأجهزة الكهربائية؟', 'يمكنك إرجاع الجهاز خلال 14 يومًا من تاريخ الاستلام بشرط عدم الاستخدام ووجود الكرتونة الأصلية.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(2, 'هل يوجد ضمان على الأجهزة؟', 'نعم، جميع الأجهزة الكهربائية بضمان معتمد من الشركة المصنعة لمدة لا تقل عن سنة.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(3, 'هل يشمل السعر التركيب؟', 'بعض الأجهزة مثل التكييفات والغسالات يشمل السعر تركيب أساسي، ويتم توضيح ذلك في صفحة المنتج.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(4, 'ما مدة توصيل الأجهزة؟', 'يتم توصيل الأجهزة خلال 2 إلى 5 أيام عمل حسب المحافظة.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(5, 'هل التوصيل داخل الشقة أم حتى باب العمارة فقط؟', 'التوصيل حتى باب الشقة، وفي بعض الحالات حتى باب العمارة حسب نوع الجهاز.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(6, 'ما هي طرق الدفع المتاحة؟', 'نقبل الدفع نقدًا عند الاستلام، البطاقات البنكية، التحويل البنكي، وخدمات التقسيط.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(7, 'هل يوجد نظام تقسيط؟', 'نعم، نوفر أنظمة تقسيط متعددة من خلال بنوك وشركات تقسيط معتمدة.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(8, 'هل يمكن فحص الجهاز قبل الاستلام؟', 'نعم، يمكنك فحص الجهاز ظاهريًا قبل الاستلام للتأكد من سلامته.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(9, 'هل تتوفر قطع غيار للأجهزة؟', 'نوفر قطع غيار أصلية لبعض الأجهزة حسب التوفر ومن خلال مراكز الخدمة المعتمدة.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(10, 'هل تقدمون صيانة بعد البيع؟', 'خدمة الصيانة تتم من خلال مراكز الخدمة المعتمدة التابعة للشركة المصنعة.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(11, 'هل الأسعار تشمل ضريبة القيمة المضافة؟', 'نعم، جميع الأسعار المعروضة شاملة ضريبة القيمة المضافة.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(12, 'هل يمكن تغيير عنوان التوصيل بعد الطلب؟', 'نعم، يمكن تعديل عنوان التوصيل قبل شحن الطلب من خلال التواصل مع خدمة العملاء.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(13, 'هل الأجهزة أصلية ومستوردة؟', 'نعم، جميع الأجهزة أصلية 100% ومستوردة من وكلاء معتمدين.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(14, 'ما هي ساعات خدمة العملاء؟', 'خدمة العملاء متاحة يوميًا من 10 صباحًا حتى 9 مساءً.', '2026-01-12 17:51:33', '2026-01-12 17:51:33'),
(15, 'هل يتم إصدار فاتورة ضريبية؟', 'نعم، يتم إصدار فاتورة ضريبية معتمدة مع كل عملية شراء.', '2026-01-12 17:51:33', '2026-01-12 17:51:33');
