INSERT INTO `pages` (`id`, `title`, `content`, `slug`, `description`, `meta_title`, `meta_description`, `image`, `status`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"About Us\",\"ar\":\"\\u0645\\u0646 \\u0646\\u062d\\u0646\"}', '{\"en\":\"We are a company dedicated to providing the best services.\",\"ar\":\"\\u0646\\u062d\\u0646 \\u0634\\u0631\\u0643\\u0629 \\u0645\\u0643\\u0631\\u0633\\u0629 \\u0644\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0623\\u0641\\u0636\\u0644 \\u0627\\u0644\\u062e\\u062f\\u0645\\u0627\\u062a.\"}', '{\"en\":\"about-us\",\"ar\":\"\\u0645\\u0646-\\u0646\\u062d\\u0646\"}', '{\"en\":\"Learn more about our company and our mission.\",\"ar\":\"\\u062a\\u0639\\u0631\\u0641 \\u0623\\u0643\\u062b\\u0631 \\u0639\\u0644\\u0649 \\u0634\\u0631\\u0643\\u062a\\u0646\\u0627 \\u0648\\u0631\\u0633\\u0627\\u0644\\u062a\\u0646\\u0627.\"}', '{\"en\":\"About Us - Company Name\",\"ar\":\"\\u0645\\u0646 \\u0646\\u062d\\u0646 - \\u0627\\u0633\\u0645 \\u0627\\u0644\\u0634\\u0631\\u0643\\u0629\"}', '{\"en\":\"Discover our journey and what we stand for.\",\"ar\":\"\\u0627\\u0643\\u062a\\u0634\\u0641 \\u0631\\u062d\\u0644\\u062a\\u0646\\u0627 \\u0648\\u0645\\u0627 \\u0646\\u0645\\u062b\\u0644\\u0647.\"}', NULL, 'Y', 1, 1, '2026-01-12 17:51:32', '2026-01-12 17:51:32'),
(2, '{\"en\":\"Contact Us\",\"ar\":\"\\u0627\\u062a\\u0635\\u0644 \\u0628\\u0646\\u0627\"}', '{\"en\":\"Feel free to reach out to us for any inquiries.\",\"ar\":\"\\u0644\\u0627 \\u062a\\u062a\\u0631\\u062f\\u062f \\u0641\\u064a \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0646\\u0627 \\u0644\\u0623\\u064a \\u0627\\u0633\\u062a\\u0641\\u0633\\u0627\\u0631\\u0627\\u062a.\"}', '{\"en\":\"contact-us\",\"ar\":\"\\u0627\\u062a\\u0635\\u0644-\\u0628\\u0646\\u0627\"}', '{\"en\":\"Get in touch with us for support or questions.\",\"ar\":\"\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0646\\u0627 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0623\\u0648 \\u0644\\u0637\\u0631\\u062d \\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629.\"}', '{\"en\":\"Contact Us - Company Name\",\"ar\":\"\\u0627\\u062a\\u0635\\u0644 \\u0628\\u0646\\u0627 - \\u0627\\u0633\\u0645 \\u0627\\u0644\\u0634\\u0631\\u0643\\u0629\"}', '{\"en\":\"Reach out for assistance and inquiries.\",\"ar\":\"\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0646\\u0627 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0633\\u0627\\u0639\\u062f\\u0629 \\u0648\\u0627\\u0644\\u0627\\u0633\\u062a\\u0641\\u0633\\u0627\\u0631\\u0627\\u062a.\"}', NULL, 'Y', 1, 1, '2026-01-12 17:51:32', '2026-01-12 17:51:32'),
(3, '{\"en\":\"Privacy Policy\",\"ar\":\"\\u0633\\u064a\\u0627\\u0633\\u0629 \\u0627\\u0644\\u062e\\u0635\\u0648\\u0635\\u064a\\u0629\"}', '{\"en\":\"We value your privacy and are committed to protecting it.\",\"ar\":\"\\u0646\\u062d\\u0646 \\u0646\\u0642\\u062f\\u0631 \\u062e\\u0635\\u0648\\u0635\\u064a\\u062a\\u0643 \\u0648\\u0645\\u0644\\u062a\\u0632\\u0645\\u0648\\u0646 \\u0628\\u062d\\u0645\\u0627\\u064a\\u062a\\u0647\\u0627.\"}', '{\"en\":\"privacy-policy\",\"ar\":\"\\u0633\\u064a\\u0627\\u0633\\u0629-\\u0627\\u0644\\u062e\\u0635\\u0648\\u0635\\u064a\\u0629\"}', '{\"en\":\"Read our privacy policy to understand how we handle data.\",\"ar\":\"\\u0627\\u0642\\u0631\\u0623 \\u0633\\u064a\\u0627\\u0633\\u0629 \\u0627\\u0644\\u062e\\u0635\\u0648\\u0635\\u064a\\u0629 \\u0644\\u062f\\u064a\\u0646\\u0627 \\u0644\\u0641\\u0647\\u0645 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u062a\\u0639\\u0627\\u0645\\u0644\\u0646\\u0627 \\u0645\\u0639 \\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a.\"}', '{\"en\":\"Privacy Policy - Company Name\",\"ar\":\"\\u0633\\u064a\\u0627\\u0633\\u0629 \\u0627\\u0644\\u062e\\u0635\\u0648\\u0635\\u064a\\u0629 - \\u0627\\u0633\\u0645 \\u0627\\u0644\\u0634\\u0631\\u0643\\u0629\"}', '{\"en\":\"Learn how we collect and protect your information.\",\"ar\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u062c\\u0645\\u0639 \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a\\u0643 \\u0648\\u062d\\u0645\\u0627\\u064a\\u062a\\u0647\\u0627.\"}', NULL, 'Y', 1, 1, '2026-01-12 17:51:32', '2026-01-12 17:51:32');
