(1, 'GLOWXIX', 'Glow Care Pharma | عناية متكاملة بالبشرة والشعر والجسم\r\nمنتجات طبيعية – جودة عالية – نتائج ملموسة ✨\r\nلأن جمالك يستاهل الأفضل 💚', 'glowxixofficial@gmail.com', '01012367393', '01036125738', '01036125738', 'مرحبا {name} في Glowxix \r\nنؤكد مع حضرتك الفااتورة : {invoice_number}\r\nاجمالي الفاتورة : {total}\r\nالمدفوع : {paid} \r\nالمتبقي {remaining} \r\nويمكنك غرض الفاتورة من خلال {link}', 'Glow Care Pharma', 'Glowxix   هو براند متخصص في منتجات العناية بالبشرة والشعر والجسم، تصنيع محلي بجودة عالية ومعايير آمنة تناسب كل أنواع البشرة.\r\nنقدم منتجات فعّالة تعتمد على مكونات مختارة بعناية لتمنحك نتائج حقيقية ولمسة جمال طبيعية.\r\nفي Laver نهتم بكل تفصيلة، من جودة التصنيع لحد تجربة الاستخدام، علشان نوصل لك أفضل عناية تستحقها بشرتك وشعرك 💚\r\n✨ لأن جمالك يستحق الأفضل… اختر Laver.', 'مدينة السادات', 'المنوفيه', 'مصر', NULL, '01012367393', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.facebook.com/share/1DWXSiooqj/?mibextid=wwXIfr', NULL, 'https://www.instagram.com/glowxix_official?igsh=MXVuczN3ZzEyM2o4Mw%3D%3D&utm_source=qr', NULL, NULL, 'https://www.tiktok.com/@glowxixofficial?_r=1&_t=ZS-93dAMrs16qV', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'EGP', 'ج.م', NULL, 1000.00, 75.00, 2, 1, 30.00, 1, NULL, 0, 1, NULL, 1, 0, 0, '{\"en\":null}', '{\"en\":null}', 'Email address', 'Sign Up', '{\"ar\":\"الشحن مجانا لطلبات تتعدى 1000جنيه\",\"en\":null}', '2026-01-12 17:51:32', '2026-09-29 18:58:47');
INSERT INTO `sliders` (`id`, `title`, `description`, `button_text`, `button_link`, `status`, `order`, `background_color`, `background_color_secondary`, `created_at`, `updated_at`) VALUES
(1, '{\"ar\":\"عناية متكاملة لبشرتك كل يوم\",\"en\":\"Complete daily skincare for your skin\"}', '{\"ar\":\"بشرة صحية تبدأ بروتين صحيح – منتجاتنا مصممة بعناية لتمنحك ترطيبًا عميقًا ونضارة تدوم طوال اليوم.\",\"en\":\"Healthy skin starts with a complete routine – our products are carefully designed to give you deep hydration and freshness that lasts all day.\"}', 'تسوق العناية بالبشرة', 'https://laver-eg.com/ar/products?category_id=1', 1, 4, '#667eea', '#764ba2', '2026-01-22 22:03:19', '2026-03-18 04:18:29'),
(2, '{\"ar\":\"دلّلي جسمك بعناية تستحقها\",\"en\":\"Give your body the care it deserves\"}', '{\"ar\":\"انتعاش يدوم طوال اليوم – بادي سبلاش يمنحك رائحة منعشة ولمسة خفيفة تضيف لجمالك حضورًا مميزًا.\",\"en\":\"All-day freshness – Body Splash gives you a fresh scent and a light touch that adds a distinctive presence to your beauty.\"}', 'اكتشف عناية الجسم', 'https://laver-eg.com/ar/products?category_id=3', 1, 2, '#667eea', '#764ba2', '2026-01-22 22:03:19', '2026-03-14 23:35:27'),
(3, '{\"ar\":\"شعر صحي ولمعان طبيعي\",\"en\":\"Healthy hair with natural shine\"}', '{\"ar\":\"لأن شعرك يستحق الأفضل – منتجات مصممة لتمنحك نعومة، ترطيبًا عميقًا، ومظهراً صحياً يدوم.\",\"en\":\"<span style=\\\"color: rgba(0, 0, 0, 0.9); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, Ubuntu, Cantarell, &quot;Noto Sans&quot;, sans-serif, Arial, &quot;PingFang SC&quot;, &quot;Source Han Sans SC&quot;, &quot;Microsoft YaHei UI&quot;, &quot;Microsoft YaHei&quot;, &quot;Noto Sans CJK SC&quot;, sans-serif; font-size: 16px; white-space: pre-wrap;\\\">Because your hair deserves nothing but the best. Our products are crafted to deliver ultimate softness, deep hydration, and a lasting, healthy radiance.</span>\"}', 'تسوق عناية الشعر', 'https://laver-eg.com/ar/products?category_id=2', 1, 3, '#667eea', '#764ba2', '2026-01-22 22:03:19', '2026-04-20 07:41:53'),
(4, '{\"ar\":\"مجموعة التفتيح والنضارة المتكاملة\",\"en\":\"Ultimate Glow & Brightening Duo\"}', '{\"ar\":\"وفري 110 جنيه! احصلي على سيروم النضارة الثلاثي وكريم التفتيح العميق الآن بـ 550 ج فقط بدلاً من 660 ج. بشرة مشرقة، موحدة، وخالية من العيوب في خطوتين.\",\"en\":\"Save 110 LE! Get our Triple Action Glow Serum + Deep Whitening Cream for only 550 LE (Instead of 660 LE). Radiant, even-toned, and flawless skin in just 2 steps.\"}', 'اشتري العرض الآن', 'https://laver-eg.com/ar/product/104', 0, 1, '#667eea', '#764ba2', '2026-03-18 04:10:19', '2026-04-01 19:06:16');
