INSERT INTO `why_choose_us` (`id`, `title`, `description`, `icon`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, '{\"ar\":\"جودة مضمونة\",\"en\":\"Guaranteed Quality\"}', '{\"ar\":\"جميع منتجاتنا طبيعية 100% . نضمن لك جودة عالية  في كل منتج تطلبيه.\",\"en\":\"All our products are 100% authentic and sourced from trusted suppliers. We guarantee quality in every product you purchase\"}', 'bi-star', 1, 1, '2026-02-12 17:10:09', '2026-09-26 16:42:31'),
(2, '{\"ar\":\"أفضل الأسعار\",\"en\":\"Best Prices\"}', '{\"ar\":\"نقدم لك أفضل الأسعار مع خصومات مستمرة وعروض حصرية طوال العام.\",\"en\":\"We offer you the best prices with continuous discounts and exclusive offers throughout the year\"}', 'bi-cash-stack', 2, 1, '2026-02-12 17:11:50', '2026-02-12 17:11:50'),
(3, '{\"ar\":\"توصيل سريع\",\"en\":\"Fast Delivery\"}', '{\"ar\":\"نوصل طلباتك في أسرع وقت ممكن. شحن مجاني للطلبات أكثر من1000 جنية .\",\"en\":\"We deliver your orders as quickly as possible. Free shipping on orders over 1000EGP.\"}', 'bi-geo-alt', 3, 1, '2026-02-12 17:12:44', '2026-09-26 16:42:20');
