  `wholesale_price` decimal(10,2) DEFAULT NULL COMMENT 'سعر البيع بالجملة',
  `wholesale_value` decimal(10,2) DEFAULT NULL COMMENT 'قيمة الخصم/الإضافة للبيع بالجملة',
  `promotional_price` decimal(10,2) DEFAULT NULL COMMENT 'سعر العرض',
